type Matrix<T> = Vec<Vec<T>>;

fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> Matrix<i8> {
    // shape must be of length 2
    assert!(shape.len() == 2, "shape must have exactly two dimensions");
    let r = shape[0] as usize;
    let c = shape[1] as usize;
    let n = a.len();
    // dimensions and array length must be positive
    assert!(r > 0 && c > 0, "matrix dimensions must be positive");
    assert!(n > 0, "input array must have positive length");
    // the array length must match one of the matrix dimensions
    assert!(
        n == r || n == c,
        "length of a must equal either R or C"
    );

    let mut mat: Matrix<i8> = Vec::with_capacity(r);
    if n == r {
        // Broadcast as column vector: each a[i] replicated across the row
        for i in 0..r {
            mat.push(vec![a[i]; c]);
        }
    } else {
        // Broadcast as row vector: the entire a cloned for each row
        for _ in 0..r {
            mat.push(a.clone());
        }
    }
    mat
}

// Example usage and simple test
fn main() {
    // Example 1: broadcast a column vector of length 3 into a 3×4 matrix
    let a = vec![1i8, 2, 3];
    let shape = vec![3u8, 4u8];
    let m = broadcast(a.clone(), shape.clone());
    assert_eq!(
        m,
        vec![
            vec![1, 1, 1, 1],
            vec![2, 2, 2, 2],
            vec![3, 3, 3, 3]
        ]
    );

    // Example 2: broadcast a row vector of length 4 into a 2×4 matrix
    let a = vec![5i8, 6, 7, 8];
    let shape = vec![2u8, 4u8];
    let m = broadcast(a.clone(), shape.clone());
    assert_eq!(
        m,
        vec![
            vec![5, 6, 7, 8],
            vec![5, 6, 7, 8]
        ]
    );

    println!("All tests passed!");
}